  uint32_t lo = 0;
  uint32_t hi = f->count;
  uint8_t b[ZH_SD_IDX_ENTRY];

  /* memo 快路径：同一字形反复查（测量→绘制→逐帧重绘）免掉整个二分 */

  if (f->m_unicode == unicode)
    {
