      *offset = f->m_offset;
      *size = f->m_size;
      *adv = f->m_adv;
      *box_w = f->m_box_w;
      *box_h = f->m_box_h;
      *ofs_x = f->m_ofs_x;
      *ofs_y = f->m_ofs_y;
      return true;
    }

  while (lo < hi)
    {
      uint32_t mid = (lo + hi) / 2;
      uint32_t u;

      if (fseek(f->fp, ZH_SD_HEADER + (long)mid * ZH_SD_IDX_ENTRY,
