  zh_bind_icon_fonts();

  /* 先断开旧 fallback（上次探测失败可能已打开部分文件） */

  s_main16.fallback = NULL;
  s_main20.fallback = NULL;
  s_main24.fallback = NULL;

  /* ⚠️ SD 兜底的字形渲染依赖 LVGL 池缓存（lv_malloc）——NSH 命令场景
