          s_main16.fallback = &s_sd_lvfont16;
          s_main20.fallback = &s_sd_lvfont20;
          s_main24.fallback = &s_sd_lvfont24;
          g_src = ZH_SRC_SD_FULL;
          printf("[Font] SD 全量字库就绪（flash 子集主字体 + SD 兜底，"
